Object.assign(SNIP,{});PRESET_NOTES["l9"]={"Ví dụ: Dựng mảng cộng dồn": "Mỗi ô pre[i+1] chỉ cần ô ngay trước nó cộng thêm a[i]: một lần duyệt O(n). Bật Đoán trước để thử đoán ô tiếp theo.", "Ví dụ: Trả lời câu hỏi tổng đoạn": "Mỗi câu hỏi chỉ đọc hai ô của pre, dù đoạn dài bao nhiêu. Thử l = r: kết quả phải bằng đúng a[l].", "Ví dụ: Bảng cộng dồn hai chiều": "Ô đang điền được tô viền. Mỗi ô dùng ba ô đã có: bên trên, bên trái và chéo trên trái. Hình chữ nhật hàng 1..2, cột 1..3 có tổng 1+1+2+5+2+1 = 12.", "Ví dụ: Đếm đoạn có tổng chia hết cho k": "cnt[du] là số tiền tố đã gặp có cùng số dư. Mỗi tiền tố mới ghép được với chừng ấy tiền tố cũ thành một đoạn chia hết cho k. Kết quả 7.", "Lỗi: quên ô pre[0] và lệch chỉ số": "Dòng đầu in 5 thay vì 8 (thiếu a[0]). Dòng sau đọc pre[−1]: trình mô phỏng dừng chương trình và báo lỗi truy cập ngoài mảng. Thêm ô pre[0] = 0 thì cả hai vấn đề biến mất."};EX_HINTS["l9"]=[["Chỉ số tính từ 1 nên dùng pre[i] = tổng i số đầu; tổng đoạn là pre[r] − pre[l − 1].", "Tổng có thể tới 10¹⁴: mảng pre phải là long long."], ["Đánh chỉ số từ 1 và để hàng 0, cột 0 bằng 0: công thức không cần trường hợp đặc biệt.", "Dựng: P[i][j] = P[i−1][j] + P[i][j−1] − P[i−1][j−1] + a[i][j]. Hỏi: trừ hai dải, cộng lại góc bị trừ hai lần."], ["Đoạn [l, r] chia hết cho k khi hai tiền tố pre[l] và pre[r+1] cùng số dư. Đừng quên tiền tố rỗng: cnt[0] = 1 trước khi duyệt.", "Số dư của số âm: ((s % k) + k) % k. Kết quả có thể tới khoảng n²/2, dùng long long."]];
