RACE_X["race-a9"]=Object.assign(RACE_X["race-a9"]||{},{cs:["using System;\n\nclass Program\n{\n    static void Main()\n    {\n        string[] t = Console.ReadLine().Split();\n        int n = int.Parse(t[0]), q = int.Parse(t[1]);\n        int[] a = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        for (int k = 0; k < q; k++)\n        {\n            string[] lr = Console.ReadLine().Split();\n            int l = int.Parse(lr[0]), r = int.Parse(lr[1]);\n            long s = 0;\n            for (int i = l; i <= r; i++) s += a[i];\n            Console.WriteLine(s);\n        }\n    }\n}", "using System;\n\nclass Program\n{\n    static void Main()\n    {\n        string[] t = Console.ReadLine().Split();\n        int n = int.Parse(t[0]), q = int.Parse(t[1]);\n        int[] a = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        long[] pre = new long[n + 1];\n        for (int i = 0; i < n; i++) pre[i + 1] = pre[i] + a[i];\n        for (int k = 0; k < q; k++)\n        {\n            string[] lr = Console.ReadLine().Split();\n            int l = int.Parse(lr[0]), r = int.Parse(lr[1]);\n            Console.WriteLine(pre[r + 1] - pre[l]);\n        }\n    }\n}"]});
RACE_X["race-a9"]=Object.assign(RACE_X["race-a9"]||{},{py:["n, q = map(int, input().split())\na = list(map(int, input().split()))\nfor _ in range(q):\n    l, r = map(int, input().split())\n    s = 0\n    for i in range(l, r + 1):\n        s += a[i]\n    print(s)", "n, q = map(int, input().split())\na = list(map(int, input().split()))\npre = [0] * (n + 1)\nfor i in range(n):\n    pre[i + 1] = pre[i] + a[i]\nfor _ in range(q):\n    l, r = map(int, input().split())\n    print(pre[r + 1] - pre[l])"]});
makeStepRace(document.getElementById("race-a9"),{variants:[{label:"Cộng lại từng đoạn: O(n · q)",code:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int n, q;\n    cin >> n >> q;\n    int a[100000];\n    for (int i = 0; i < n; i++) cin >> a[i];\n    while (q--) {\n        int l, r;\n        cin >> l >> r;\n        long long s = 0;\n        for (int i = l; i <= r; i++) s += a[i];\n        cout << s << \"\\n\";\n    }\n    return 0;\n}"},{label:"Mảng cộng dồn: O(n + q)",code:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int n, q;\n    cin >> n >> q;\n    long long pre[100001];\n    pre[0] = 0;\n    for (int i = 0; i < n; i++) {\n        int x;\n        cin >> x;\n        pre[i + 1] = pre[i] + x;\n    }\n    while (q--) {\n        int l, r;\n        cin >> l >> r;\n        cout << pre[r + 1] - pre[l] << \"\\n\";\n    }\n    return 0;\n}"}],gen:n=>n+" "+n+"\n"+Array.from({length:n},(_,i)=>(i*37)%101).join(" ")+"\n"+Array.from({length:n},(_,i)=>{const l=(i*13)%n,r=Math.min(n-1,l+n/2|0);return l+" "+r}).join("\n"),ns:[50,100,200,400],note:"n số và q = n câu hỏi, mỗi đoạn dài khoảng n/2. Cộng lại từng đoạn: n tăng gấp đôi thì số bước gấp khoảng bốn. Mảng cộng dồn: chỉ gấp đôi."});
const PR9=[{label:"Ví dụ: Dựng mảng cộng dồn",input:"",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> a = {3, 1, 4, 1, 5, 9};\n    int n = a.size();\n    vector<long long> pre(n + 1, 0);\n    for (int i = 0; i < n; i++) {\n        pre[i + 1] = pre[i] + a[i];\n    }\n    for (int i = 0; i <= n; i++) cout << pre[i] << \" \";\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"a",ptr:["i"]},{type:"cells",of:"pre",ptr:["i+1"],label:"pre"}],predict:[{line:10,v:"i+1",q:"Dòng này sẽ ghi vào ô nào của pre? (bấm vào ô trong hàng pre)"}],py:{code:"a = [3, 1, 4, 1, 5, 9]\nn = len(a)\npre = [0] * (n + 1)\nfor i in range(n):\n    pre[i + 1] = pre[i] + a[i]\nprint(*pre)",predict:[{line:5,v:"i+1",q:"Dòng này sẽ ghi vào ô nào của pre? (bấm vào ô trong hàng pre)"}]},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] a = { 3, 1, 4, 1, 5, 9 };\n        int n = a.Length;\n        long[] pre = new long[n + 1];\n        for (int i = 0; i < n; i++)\n        {\n            pre[i + 1] = pre[i] + a[i];\n        }\n        Console.WriteLine(string.Join(\" \", pre));\n    }\n}",predict:[{line:12,v:"i+1",q:"Dòng này sẽ ghi vào ô nào của pre? (bấm vào ô trong hàng pre)"}]}},{label:"Ví dụ: Trả lời câu hỏi tổng đoạn",input:"3\n1 3\n0 5\n4 4",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> a = {3, 1, 4, 1, 5, 9};\n    int n = a.size();\n    vector<long long> pre(n + 1, 0);\n    for (int i = 0; i < n; i++) pre[i + 1] = pre[i] + a[i];\n    int q;\n    cin >> q;\n    while (q--) {\n        int l, r;\n        cin >> l >> r;\n        cout << \"Tong a[\" << l << \"..\" << r << \"] = \" << pre[r + 1] - pre[l] << \"\\n\";\n    }\n    return 0;\n}",viz:[{type:"cells",of:"a",range:["l","r"]},{type:"cells",of:"pre",ptr:["l","r+1"],label:"pre"}],py:{code:"a = [3, 1, 4, 1, 5, 9]\nn = len(a)\npre = [0] * (n + 1)\nfor i in range(n):\n    pre[i + 1] = pre[i] + a[i]\nq = int(input())\nfor _ in range(q):\n    l, r = map(int, input().split())\n    print(f\"Tong a[{l}..{r}] = {pre[r + 1] - pre[l]}\")"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] a = { 3, 1, 4, 1, 5, 9 };\n        int n = a.Length;\n        long[] pre = new long[n + 1];\n        for (int i = 0; i < n; i++) pre[i + 1] = pre[i] + a[i];\n        int q = int.Parse(Console.ReadLine());\n        for (int k = 0; k < q; k++)\n        {\n            string[] t = Console.ReadLine().Split();\n            int l = int.Parse(t[0]), r = int.Parse(t[1]);\n            Console.WriteLine($\"Tong a[{l}..{r}] = {pre[r + 1] - pre[l]}\");\n        }\n    }\n}"}},{label:"Ví dụ: Bảng cộng dồn hai chiều",input:"",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int a[3][4] = {{1, 2, 0, 3}, {4, 1, 1, 2}, {0, 5, 2, 1}};\n    int P[4][5] = {};\n    for (int i = 0; i < 3; i++) {\n        for (int j = 0; j < 4; j++) {\n            P[i + 1][j + 1] = P[i][j + 1] + P[i + 1][j] - P[i][j] + a[i][j];\n        }\n    }\n    // tổng hình chữ nhật hàng 1..2, cột 1..3\n    int r1 = 1, c1 = 1, r2 = 2, c2 = 3;\n    cout << P[r2 + 1][c2 + 1] - P[r1][c2 + 1] - P[r2 + 1][c1] + P[r1][c1] << \"\\n\";\n    return 0;\n}",viz:[{type:"grid",of:"a",cur:["i","j"],label:"a"},{type:"grid",of:"P",cur:["i+1","j+1"],label:"P (lệch một hàng, một cột)"}],py:{code:"a = [[1, 2, 0, 3], [4, 1, 1, 2], [0, 5, 2, 1]]\nP = [[0] * 5 for _ in range(4)]\nfor i in range(3):\n    for j in range(4):\n        P[i + 1][j + 1] = P[i][j + 1] + P[i + 1][j] - P[i][j] + a[i][j]\n# tổng hình chữ nhật hàng 1..2, cột 1..3\nr1, c1, r2, c2 = 1, 1, 2, 3\nprint(P[r2 + 1][c2 + 1] - P[r1][c2 + 1] - P[r2 + 1][c1] + P[r1][c1])",note:"Ô đang điền được tô viền. Mỗi ô dùng ba ô đã có: bên trên, bên trái và chéo trên trái. Tạo bảng bằng [[0] * 5 for _ in range(4)], đừng viết [[0] * 5] * 4 (bốn hàng sẽ là cùng một list)."},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int[][] a =\n        {\n            new int[] { 1, 2, 0, 3 },\n            new int[] { 4, 1, 1, 2 },\n            new int[] { 0, 5, 2, 1 }\n        };\n        int[][] P = new int[4][];\n        for (int i = 0; i < 4; i++) P[i] = new int[5];\n        for (int i = 0; i < 3; i++)\n        {\n            for (int j = 0; j < 4; j++)\n            {\n                P[i + 1][j + 1] = P[i][j + 1] + P[i + 1][j] - P[i][j] + a[i][j];\n            }\n        }\n        // tổng hình chữ nhật hàng 1..2, cột 1..3\n        int r1 = 1, c1 = 1, r2 = 2, c2 = 3;\n        Console.WriteLine(P[r2 + 1][c2 + 1] - P[r1][c2 + 1] - P[r2 + 1][c1] + P[r1][c1]);\n    }\n}",note:"C# dùng mảng răng cưa int[][]: mảng của các hàng, mỗi hàng tạo bằng new int[5]. Phần tử viết P[i][j]. P có thêm hàng 0 và cột 0 bằng 0 để công thức không cần trường hợp đặc biệt."}},{label:"Ví dụ: Đếm đoạn có tổng chia hết cho k",input:"",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> a = {4, 5, 0, -2, -3, 1};\n    int k = 5;\n    vector<int> cnt(k, 0);\n    cnt[0] = 1;          // tiền tố rỗng có tổng 0\n    long long s = 0, dem = 0;\n    for (int x : a) {\n        s += x;\n        int du = ((s % k) + k) % k;\n        dem += cnt[du];\n        cnt[du]++;\n    }\n    cout << dem << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"a"},{type:"cells",of:"cnt",ptr:["du"],label:"cnt[số dư]"},{type:"vars",names:["s","du","dem"]}],py:{code:"a = [4, 5, 0, -2, -3, 1]\nk = 5\ncnt = [0] * k\ncnt[0] = 1          # tiền tố rỗng có tổng 0\ns = 0\ndem = 0\nfor x in a:\n    s += x\n    du = s % k\n    dem += cnt[du]\n    cnt[du] += 1\nprint(dem)",note:"cnt[du] là số tiền tố đã gặp có cùng số dư. Trong Python, s % k luôn nằm trong 0..k−1 kể cả khi s âm, nên không cần chỉnh như C++. Kết quả 7."},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] a = { 4, 5, 0, -2, -3, 1 };\n        int k = 5;\n        int[] cnt = new int[k];\n        cnt[0] = 1;          // tiền tố rỗng có tổng 0\n        long s = 0, dem = 0;\n        foreach (int x in a)\n        {\n            s += x;\n            int du = (int)(((s % k) + k) % k);\n            dem += cnt[du];\n            cnt[du]++;\n        }\n        Console.WriteLine(dem);\n    }\n}",note:"Với số âm, % của C# cho số dư âm (−7 % 3 = −1), nên đưa về 0..k−1 bằng ((s % k) + k) % k. s là long nên kết quả cũng là long: ép (int) để dùng làm chỉ số."}},{label:"Lỗi: quên ô pre[0] và lệch chỉ số",input:"",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> a = {3, 1, 4, 1, 5, 9};\n    int n = a.size();\n    vector<long long> pre(n, 0);\n    pre[0] = a[0];\n    for (int i = 1; i < n; i++) pre[i] = pre[i - 1] + a[i];\n    int l = 0, r = 2;\n    // sai: thiếu a[l]; và với l = 0 thì pre[l - 1] ra ngoài mảng\n    cout << pre[r] - pre[l] << \"\\n\";\n    cout << pre[r] - pre[l - 1] << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"pre",ptr:["l","r"],label:"pre (thiếu ô 0)"}],py:{code:"a = [3, 1, 4, 1, 5, 9]\nn = len(a)\npre = [0] * n\npre[0] = a[0]\nfor i in range(1, n):\n    pre[i] = pre[i - 1] + a[i]\nl, r = 0, 2\n# sai: thiếu a[l]; và với l = 0 thì pre[l - 1] là pre[-1]\nprint(pre[r] - pre[l])\nprint(pre[r] - pre[l - 1])",note:"Dòng đầu in 5 thay vì 8 (thiếu a[0]). Dòng sau còn nguy hiểm hơn: Python hiểu pre[-1] là phần tử CUỐI nên không báo lỗi, chỉ ra kết quả sai (8 − 23 = −15). Thêm ô pre[0] = 0 thì cả hai vấn đề biến mất."},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] a = { 3, 1, 4, 1, 5, 9 };\n        int n = a.Length;\n        long[] pre = new long[n];\n        pre[0] = a[0];\n        for (int i = 1; i < n; i++) pre[i] = pre[i - 1] + a[i];\n        int l = 0, r = 2;\n        // sai: thiếu a[l]; và với l = 0 thì pre[l - 1] ra ngoài mảng\n        Console.WriteLine(pre[r] - pre[l]);\n        Console.WriteLine(pre[r] - pre[l - 1]);\n    }\n}",note:"Dòng đầu in 5 thay vì 8 (thiếu a[0]). Dòng sau truy cập pre[-1]: C# kiểm tra chỉ số và dừng chương trình với IndexOutOfRangeException. Thêm ô pre[0] = 0 thì cả hai lỗi biến mất."}}];
