makeEx2(document.getElementById("ex-l9"),sim9,[{t:"Tổng đoạn",d:"Đầu vào: n và q (1 ≤ n, q ≤ 10^5), dòng sau n số nguyên a₁..aₙ (|aᵢ| ≤ 10^9), rồi q dòng, mỗi dòng l r (1 ≤ l ≤ r ≤ n, chỉ số tính từ 1). Đầu ra: với mỗi câu hỏi, in tổng aₗ + … + aᵣ trên một dòng.",tests:[{in:"5 3\n2 -1 3 5 4\n1 3\n2 5\n4 4",out:"4\n11\n5"},{in:"1 1\n1000000000\n1 1",out:"1000000000"},{in:"4 2\n1000000000 1000000000 1000000000 1000000000\n1 4\n2 3",out:"4000000000\n2000000000"},{in:"3 2\n-5 -5 -5\n1 3\n2 2",out:"-15\n-5"}],start:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int n, q;\n    cin >> n >> q;\n    // dựng mảng cộng dồn (long long) rồi trả lời từng câu hỏi\n    return 0;\n}",perf:{gen:n=>n+" "+n+"\n"+Array.from({length:n},(_,i)=>((i*7919)%2000001)-1000000).join(" ")+"\n"+Array.from({length:n},(_,i)=>{const l=(i*31)%n,r=Math.min(n-1,l+(n>>1));return (l+1)+" "+(r+1)}).join("\n"),ns:[500,2000,8000],need:"n",limit:n=>45*n+200,why:"Cộng lại từng đoạn tốn O(n · q). Dựng mảng cộng dồn một lần rồi trả lời mỗi câu bằng một phép trừ."},py:{start:"n, q = map(int, input().split())\na = list(map(int, input().split()))\n# dựng mảng cộng dồn rồi trả lời từng câu hỏi",hints:["Chỉ số từ 1 nên dùng pre[i] = tổng i số đầu; tổng đoạn là pre[r] − pre[l − 1].","Cộng lại sum(a[l-1:r]) cho mỗi câu hỏi là O(n · q): quá chậm."]},cs:{start:"using System;\nusing System.Text;\n\nclass Program\n{\n    static void Main()\n    {\n        string[] t = Console.ReadLine().Split();\n        int n = int.Parse(t[0]), q = int.Parse(t[1]);\n        int[] a = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        // dựng mảng cộng dồn (long) rồi trả lời từng câu hỏi\n    }\n}",hints:["Chỉ số đề tính từ 1 nên dùng pre[i] = tổng i số đầu (pre[i] = pre[i − 1] + a[i − 1]); tổng đoạn là pre[r] − pre[l − 1].","Tổng có thể tới 10¹⁴: mảng pre phải là long.","Nhiều dòng kết quả: gom vào StringBuilder rồi in một lần."]}},{t:"Tổng hình chữ nhật",d:"Đầu vào: n m (1 ≤ n, m ≤ 500), n dòng mỗi dòng m số nguyên không âm (≤ 10^6), số câu hỏi q (≤ 10^5), rồi q dòng r1 c1 r2 c2 (1 ≤ r1 ≤ r2 ≤ n, 1 ≤ c1 ≤ c2 ≤ m). Đầu ra: tổng các ô thuộc hình chữ nhật từ (r1, c1) tới (r2, c2) cho mỗi câu hỏi.",tests:[{in:"3 4\n1 2 0 3\n4 1 1 2\n0 5 2 1\n3\n2 2 3 4\n1 1 3 4\n3 1 3 1",out:"12\n22\n0"},{in:"1 1\n7\n1\n1 1 1 1",out:"7"},{in:"2 2\n1000000 1000000\n1000000 1000000\n2\n1 1 2 2\n1 2 2 2",out:"4000000\n2000000"}],start:"#include <iostream>\nusing namespace std;\n\nlong long P[501][501];\n\nint main() {\n    int n, m;\n    cin >> n >> m;\n    // P[i][j] = tổng hình chữ nhật từ (1,1) tới (i,j)\n    return 0;\n}",perf:{gen:n=>n+" "+n+"\n"+Array.from({length:n},(_,i)=>Array.from({length:n},(_,j)=>(i*31+j*17)%100).join(" ")).join("\n")+"\n"+n+"\n"+Array.from({length:n},(_,i)=>{const a=(i*7)%n,b=(i*11)%n;return "1 1 "+n+" "+n}).join("\n"),ns:[20,40,80],need:"n2",limit:n=>40*n*n+40*n+200,why:"Cộng lại từng ô của mỗi hình chữ nhật tốn O(n·m) mỗi câu hỏi. Bảng cộng dồn trả lời mỗi câu trong O(1)."},py:{start:"n, m = map(int, input().split())\n# P[i][j] = tổng hình chữ nhật từ (1,1) tới (i,j)",hints:["Đánh chỉ số từ 1 và để hàng 0, cột 0 bằng 0: công thức không cần trường hợp đặc biệt.","Tạo bảng bằng [[0] * (m + 1) for _ in range(n + 1)].","Dựng: P[i][j] = P[i−1][j] + P[i][j−1] − P[i−1][j−1] + a[i][j]. Hỏi: trừ hai dải, cộng lại góc bị trừ hai lần."]},cs:{start:"using System;\nusing System.Text;\n\nclass Program\n{\n    static void Main()\n    {\n        string[] t = Console.ReadLine().Split();\n        int n = int.Parse(t[0]), m = int.Parse(t[1]);\n        long[][] P = new long[n + 1][];\n        for (int i = 0; i <= n; i++) P[i] = new long[m + 1];\n        // P[i][j] = tổng hình chữ nhật từ (1,1) tới (i,j)\n    }\n}",hints:["Đánh chỉ số từ 1 và để hàng 0, cột 0 bằng 0: công thức không cần trường hợp đặc biệt.","Dựng: P[i][j] = P[i−1][j] + P[i][j−1] − P[i−1][j−1] + a[i][j]. Hỏi: trừ hai dải, cộng lại góc bị trừ hai lần.","Mảng hai chiều trong C# viết dạng răng cưa long[][]: tạo mảng các hàng rồi tạo từng hàng."]}},{t:"Đoạn có tổng chia hết cho k",d:"Đầu vào: n và k (1 ≤ n ≤ 10^5, 1 ≤ k ≤ 10^5), rồi n số nguyên (|aᵢ| ≤ 10^9). Đầu ra: số đoạn liên tiếp (khác rỗng) có tổng chia hết cho k.",tests:[{in:"6 5\n4 5 0 -2 -3 1",out:"7"},{in:"1 3\n3",out:"1"},{in:"3 2\n1 1 1",out:"2"},{in:"4 1\n5 -2 7 0",out:"10"},{in:"3 4\n-1 -2 -3",out:"0"}],start:"#include <iostream>\nusing namespace std;\n\nint cnt[100000];\n\nint main() {\n    int n, k;\n    cin >> n >> k;\n    // cnt[du] = số tiền tố đã gặp có số dư du\n    return 0;\n}",perf:{gen:n=>n+" 7\n"+Array.from({length:n},(_,i)=>((i*7919)%201)-100).join(" "),ns:[500,2000,8000],need:"n",limit:n=>30*n+200,why:"Thử mọi đoạn là O(n²). Gom các tiền tố theo số dư thì chỉ cần một lần duyệt."},py:{start:"n, k = map(int, input().split())\na = list(map(int, input().split()))\n# cnt[du] = số tiền tố đã gặp có số dư du",hints:["Đoạn [l, r] chia hết cho k khi hai tiền tố pre[l] và pre[r+1] cùng số dư. Đừng quên tiền tố rỗng: cnt[0] = 1 trước khi duyệt.","Trong Python, s % k với k > 0 luôn cho số dư không âm."]},cs:{start:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        string[] t = Console.ReadLine().Split();\n        int n = int.Parse(t[0]), k = int.Parse(t[1]);\n        int[] a = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        int[] cnt = new int[k];\n        // cnt[du] = số tiền tố đã gặp có số dư du\n    }\n}",hints:["Đoạn [l, r] chia hết cho k khi hai tiền tố pre[l] và pre[r+1] cùng số dư. Đừng quên tiền tố rỗng: cnt[0] = 1 trước khi duyệt.","Số dư của số âm: ((s % k) + k) % k, rồi ép (int) để làm chỉ số. Kết quả có thể tới khoảng n²/2: dùng long."]}}]);

makeQuiz("quiz9","score9",[{"q": "Với pre[0] = 0 và pre[i+1] = pre[i] + a[i] (chỉ số a từ 0), tổng a[2..5] bằng?", "o": ["pre[5] − pre[2]", "pre[6] − pre[2]", "pre[6] − pre[1]", "pre[5] − pre[1]"], "a": 1, "e": "sum(l, r) = pre[r+1] − pre[l] = pre[6] − pre[2]."}, {"q": "n = q = 10⁵. Dùng mảng cộng dồn, tổng số phép tính cỡ?", "o": ["10⁵", "2·10⁵", "10¹⁰", "n log n"], "a": 1, "e": "O(n) để dựng và O(1) mỗi câu hỏi: khoảng n + q = 2·10⁵."}, {"q": "Vì sao mảng cộng dồn nên khai báo long long dù mỗi aᵢ vừa kiểu int?", "o": ["Để chạy nhanh hơn", "Vì tổng nhiều số có thể vượt giới hạn int", "Vì C++ bắt buộc", "Để đọc được số âm"], "a": 1, "e": "10⁵ số, mỗi số 10⁹ cho tổng 10¹⁴, vượt xa int (khoảng 2,1·10⁹).", "lang": ["cpp"]}, {"q": "Trong bảng cộng dồn hai chiều, vì sao phải cộng lại P[r1][c1]?", "o": ["Để làm tròn", "Vì góc trên trái bị trừ hai lần", "Vì chỉ số bắt đầu từ 1", "Không cần cộng lại"], "a": 1, "e": "Hai dải bị trừ cùng chứa góc trên trái, nên góc này bị trừ hai lần; cộng lại một lần (bao hàm – loại trừ)."}, {"q": "Vì sao mảng cộng dồn nên khai báo long[] dù mỗi aᵢ vừa kiểu int?", "o": ["Để chạy nhanh hơn", "Vì tổng nhiều số có thể vượt giới hạn int", "Vì C# bắt buộc", "Để đọc được số âm"], "a": 1, "e": "10⁵ số, mỗi số 10⁹ cho tổng 10¹⁴, vượt xa int (khoảng 2,1·10⁹). C# không báo lỗi khi tràn: kết quả chỉ lặng lẽ sai.", "lang": ["cs"]}]);

